import { test } from 'node:test';
import assert from 'node:assert/strict';
import { diffTokens, readCustomProperties, tokensFrom } from '../src/css.js';

const SHEET = `
/* generated by Style Dictionary — do not edit */
:root {
  --ed-color-brand: #be6700;
  --ed-radius: 4px; /* tweak me */
  --ed-font: "Inter", sans-serif;
  color: red;
}
.bfw-dark {
  --ed-color-brand: #ffb36b;
}
@media (min-width: 40em) {
  :root { --ed-gap: 1.5rem }
}
.semi { content: "a;b"; --after-string: 2px; }
`;

test('reads every custom property with the selector it sits under', () => {
  const decls = readCustomProperties(SHEET);
  assert.deepEqual(
    decls.map((d) => [d.name, d.value, d.selector]),
    [
      ['--ed-color-brand', '#be6700', ':root'],
      ['--ed-radius', '4px', ':root'],
      ['--ed-font', '"Inter", sans-serif', ':root'],
      ['--ed-color-brand', '#ffb36b', '.bfw-dark'],
      ['--ed-gap', '1.5rem', ':root'],
      ['--after-string', '2px', '.semi'],
    ],
  );
});

test('a semicolon or brace inside a string does not end a declaration', () => {
  assert.deepEqual(tokensFrom('.x { --label: "a;b}c"; --n: 1; }'), { '--label': '"a;b}c"', '--n': '1' });
});

test('the last declaration wins, and --selector narrows to one block', () => {
  assert.equal(tokensFrom(SHEET)['--ed-color-brand'], '#ffb36b');
  assert.equal(tokensFrom(SHEET, { selector: ':root' })['--ed-color-brand'], '#be6700');
  assert.equal(tokensFrom(SHEET, { selector: ':root' })['--ed-gap'], '1.5rem');
});

test('diff reports what changed and what disappeared', () => {
  const { changed, removed } = diffTokens({ '--a': '1px', '--b': 'red', '--gone': '0' }, { '--a': '1px', '--b': 'blue', '--new': '2px' });
  assert.deepEqual(changed, { '--b': 'blue', '--new': '2px' });
  assert.deepEqual(removed, ['--gone']);
});
